const input = $input.first().json;
let jsonString = null; // Ищем текст во всех возможных местах
const possiblePaths = [ 'text', 'result.text', 'message.text', 'output.text', 'response.text'
]; for (const path of possiblePaths) { const keys = path.split('.'); let value = input; for (const key of keys) { value = value?.[key]; } if (value && typeof value === 'string') { jsonString = value; break; }
} if (!jsonString) { console.log('Доступные поля:', JSON.stringify(Object.keys(input), null, 2)); throw new Error('Текст не найден. Проверьте консоль для списка полей');
} try { const startIdx = jsonString.indexOf('{'); const endIdx = jsonString.lastIndexOf('}'); if (startIdx === -1 || endIdx === -1) { throw new Error('JSON не найден'); } const parsed = JSON.parse(jsonString.substring(startIdx, endIdx + 1)); return { json: { ...input, ...parsed } };
} catch (error) { throw new Error(`Parse error: ${error.message}`);
}

// Получаем текст из сообщения
const input = $input.first().json;
const userText = input.message?.caption || input.message?.text || ''; // Получаем binary данные
const binaryData = $input.first().binary; return { json: { prompt: `Ты нутрициолог. Пользователь прислал фото еды с комментарием: "${userText}". Используй комментарий для уточнения состава (вес, ингредиенты, способ приготовления). Оцени вес, БЖУ и микроэлементы. Верни ТОЛЬКО JSON в формате: {"Meal_description": "описание, вес", "Calories": 0, "Proteins": 0, "Carbs": 0, "Fats": 0, "Магний": 0, "Витамин D": 0, "Омега-3 (EPA/DHA)": 0, "Селен": 0, "Йод": 0, "Калий": 0, "Железо": 0, "Кальций": 0, "Витамин B12": 0, "Витамин К": 0, "Витамин Е": 0, "Цинк": 0, "Клетчатка": 0, """"Добавленный сахар": 0, "Натрий": 0, "Кофеин": 0, "Алкоголь": 0, "Вода": 0, "Насыщенные жиры": 0, "Трансжиры": 0}`, hasImage: true, userText: userText }, binary: binaryData
};

// Получаем binary данные
const binaryData = $input.first().binary; return { json: { prompt: `Ты нутрициолог. Пользователь прислал фото еды. Оцени вес, способ приготовления, рассчитай БЖУ и микроэлементы. Верни ТОЛЬКО JSON в формате: {"Meal_description": "описание, вес", "Calories": 0, "Proteins": 0, "Carbs": 0, "Fats": 0, "Магний": 0, "Витамин D": 0, "Омега-3 (EPA/DHA)": 0, "Селен": 0, "Йод": 0, "Калий": 0, "Железо": 0, "Кальций": 0, "Витамин B12": 0, "Витамин К": 0, "Витамин Е": 0, "Цинк": 0, "Клетчатка": 0, """"Добавленный сахар": 0, "Натрий": 0, "Кофеин": 0, "Алкоголь": 0, "Вода": 0, "Насыщенные жиры": 0, "Трансжиры": 0}`, hasImage: true, userText: '' }, binary: binaryData
};

// Получаем текст из сообщения
const input = $input.first().json;
const userText = input.message?.text || ''; return { json: { prompt: `Ты нутрициолог. Пользователь описал еду текстом: "${userText}". Оцени вес, способ приготовления, рассчитай БЖУ и микроэлементы. Верни ТОЛЬКО JSON в формате: {"Meal_description": "описание, вес", "Calories": 0, "Proteins": 0, "Carbs": 0, "Fats": 0, "Магний": 0, "Витамин D": 0, "Омега-3 (EPA/DHA)": 0, "Селен": 0, "Йод": 0, "Калий": 0, "Железо": 0, "Кальций": 0, "Витамин B12": 0, "Витамин К": 0, "Витамин Е": 0, "Цинк": 0, "Клетчатка": 0, """"Добавленный сахар": 0, "Натрий": 0, "Кофеин": 0, "Алкоголь": 0, "Вода": 0, "Насыщенные жиры": 0, "Трансжиры": 0}`, hasImage: false, userText: userText }
};

// --- НАСТРОЙКИ НОРМ (Дневные) ---
const NORMS = { cal: 2400, prot: 160, carb: 270, fat: 90
}; const items = $input.all();
const triggerData = $('Food diary').first().json; const user = triggerData.callback_query ? triggerData.callback_query.from : triggerData.message.from;
const currentUserId = `${user.first_name} ${user.last_name || ''}`.trim(); const command = triggerData.callback_query?.data || triggerData.message?.text || '/today';
const isWeek = command.includes('week'); let stats = { cal: 0, prot: 0, carb: 0, fat: 0 };
let count = 0; const vlaTime = new Date(new Date().getTime() + (10 * 60 * 60 * 1000));
const todayStr = vlaTime.toISOString().split('T')[0]; const weekAgoTime = new Date(vlaTime.getTime() - (6 * 24 * 60 * 60 * 1000));
const weekAgoStr = weekAgoTime.toISOString().split('T')[0]; for (const item of items) { const row = item.json; if (row.User_ID !== currentUserId || !row.Date) continue; const rowDate = row.Date.split('T')[0]; const isMatch = isWeek ? (rowDate >= weekAgoStr && rowDate <= todayStr) : (rowDate === todayStr); if (isMatch) { stats.cal += Number(row.Calories) || 0; stats.prot += Number(row.Proteins) || 0; stats.carb += Number(row.Carbs) || 0; stats.fat += Number(row.Fats) || 0; count++; }
} function generateBar(current, target) { const segments = 10; const progress = Math.min(Math.round((current / target) * segments), segments); const percentage = Math.round((current / target) * 100); return '🟩'.repeat(progress) + '⬜'.repeat(segments - progress) + ` ${percentage}%`;
} const multiplier = isWeek ? 7 : 1;
const periodText = isWeek ? `за 7 дней (${weekAgoStr} — ${todayStr})` : `за сегодня (${todayStr})`; const message = count > 0 ?[ `📊 *Статистика ${periodText}:*`, ``, `🔥 *Калории:* ${Math.round(stats.cal)} / ${NORMS.cal * multiplier}`, generateBar(stats.cal, NORMS.cal * multiplier), ``, `🥩 *Белки:* ${Math.round(stats.prot)}г / ${NORMS.prot * multiplier}г`, generateBar(stats.prot, NORMS.prot * multiplier), ``, `🍚 *Углеводы:* ${Math.round(stats.carb)}г / ${NORMS.carb * multiplier}г`, generateBar(stats.carb, NORMS.carb * multiplier), ``, `🥑 *Жиры:* ${Math.round(stats.fat)}г / ${NORMS.fat * multiplier}г`, generateBar(stats.fat, NORMS.fat * multiplier) ].join('\n') : `📊 ${isWeek ? 'За последние 7 дней' : 'За сегодня'} записей не найдено.`; return[{ json: { text: message, reply_markup: { inline_keyboard: [[ { text: '☀️ Сегодня', callback_data: '/today' }, { text: '📅 Неделя', callback_data: '/week' } ] ] } }
}];

const input = $input.first().json;
const query = input.callback_query || input.body?.callback_query; 

if (!query) return []; 

// Безопасно бьем строку, даже если data пришла пустой
const actionData = (query.data || '').split('|'); 
const action = actionData[0] || null;
const rowId = actionData[1] || null; 

// Перенесли return на новую строку и добавили ?. для защиты от пустых message
return [{ 
  json: { 
    callbackQueryId: query.id, 
    chatId: query.message?.chat?.id || null, 
    messageId: query.message?.message_id || null, 
    action: action, 
    rowId: rowId, 
    originalText: query.message?.text || "", 
    answerText: action === 'edit' ? 'Жду новые данные' : 'Принято' 
  }
}];

const input = $input.first().json;
const correction = input.message.text; const replyText = input.message.reply_to_message?.text || ""; // Извлекаем ID из текста сообщения бота, на которое ответил юзер
const idMatch = replyText.match(/\[ID:(\d+)\]/);
const entryId = idMatch ? idMatch[1] : null; // Извлекаем старое описание блюда (оно в первой строке после "🍽 ")
const descMatch = replyText.match(/🍽 (.*?)\n/);
const originalText = descMatch ? descMatch[1] : "неизвестно"; return { json: { prompt: `Пользователь вносит правку в блюдо. \nВот старое описание: "${originalText}". \nВот правка пользователя: "${correction}". \nПересчитай ВСЕ параметры: калории, БЖУ, полезные и вредные жиры, клетчатку, сахар, ЛПВП, ЛПНП), натрий, кофеин, алкоголь и все микроэлементы. Верни ТОЛЬКО строгий JSON со ВСЕМИ полями.`, Entry_ID: entryId }
};

